@Test
public void testAbsolutelyRequiredOption() {
    OptionRule rule = OptionRule.builder().required(TEST_PORTS, KEY_USERNAME, KEY_PASSWORD).build();
    Map<String, Object> config = new HashMap<>();
    Executable executable = () -> validate(config, rule);
    // absent
    config.put(TEST_PORTS.key(), "[9090]");
    assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - There are unconfigured options, the options('username', 'password') are required.", assertThrows(OptionValidationException.class, executable).getMessage());
    config.put(KEY_USERNAME.key(), "asuka");
    assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - There are unconfigured options, the options('password') are required.", assertThrows(OptionValidationException.class, executable).getMessage());
    // all present
    config.put(KEY_PASSWORD.key(), "saitou");
    Assertions.assertDoesNotThrow(executable);
}

@Test
public void testBundledRequiredOptions() {
    OptionRule rule = OptionRule.builder().bundled(KEY_USERNAME, KEY_PASSWORD).build();
    Map<String, Object> config = new HashMap<>();
    Executable executable = () -> validate(config, rule);
    // case1: all absent
    Assertions.assertDoesNotThrow(executable);
    // case2: some present
    config.put(KEY_USERNAME.key(), "asuka");
    assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - These options('username', 'password') are bundled, must be present or absent together." + " The options present are: 'username'. The options absent are 'password'.", assertThrows(OptionValidationException.class, executable).getMessage());
    // case2: all present
    config.put(KEY_PASSWORD.key(), "saitou");
    Assertions.assertDoesNotThrow(executable);
}

@Test
public void testSimpleExclusiveRequiredOptions() {
    OptionRule rule = OptionRule.builder().exclusive(TEST_TOPIC_PATTERN, TEST_TOPIC).build();
    Map<String, Object> config = new HashMap<>();
    Executable executable = () -> validate(config, rule);
    // all absent
    assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - There are unconfigured options, these options('option.topic-pattern', 'option.topic') are mutually exclusive," + " allowing only one set(\"[] for a set\") of options to be configured.", assertThrows(OptionValidationException.class, executable).getMessage());
    // only one present
    config.put(TEST_TOPIC_PATTERN.key(), "asuka");
    Assertions.assertDoesNotThrow(executable);
    // present > 1
    config.put(TEST_TOPIC.key(), "[\"saitou\"]");
    assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - These options('option.topic-pattern', 'option.topic') are mutually exclusive, " + "allowing only one set(\"[] for a set\") of options to be configured.", assertThrows(OptionValidationException.class, executable).getMessage());
}

