    // 'username' == asuka, and required options absent
    config.put(KEY_USERNAME.key(), "asuka");
    assertEquals("ErrorCode:[API-02], ErrorDescription:[Option item validate failed] - There are unconfigured options, the options('option.timestamp') are required" + " because ['username' == ashulin || 'username' == asuka] is true.", assertThrows(OptionValidationException.class, executable).getMessage());
    // Expression match, and required options all present
    config.put(TEST_TIMESTAMP.key(), "564231238596789");
    Assertions.assertDoesNotThrow(executable);
