        Common.setDeployMode(DeployMode.CLIENT);
        ImmutablePair<String, String> testResources = createTestResources(testCaseName, JobMode.STREAMING, testRowNumber, testParallelism);
        JobConfig jobConfig = new JobConfig();
        jobConfig.setName(testCaseName);
        ClientConfig clientConfig = ConfigProvider.locateAndGetClientConfig();
        clientConfig.setClusterName(TestUtils.getClusterName(testClusterName));
        engineClient = new SeaTunnelClient(clientConfig);
        ClientJobExecutionEnvironment jobExecutionEnv = engineClient.createExecutionContext(testResources.getRight(), jobConfig);
        ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        Long jobId = clientJobProxy.getJobId();
        ClientJobProxy finalClientJobProxy = clientJobProxy;
        Awaitility.await().atMost(600000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            // Wait some tasks commit finished, and we can get rows from the
            // sink target dir
            Thread.sleep(2000);
            System.out.println("\n=================================" + FileUtils.getFileLineNumberFromDir(testResources.getLeft()) + "=================================\n");
            Assertions.assertTrue(JobStatus.RUNNING.equals(finalClientJobProxy.getJobStatus()) && FileUtils.getFileLineNumberFromDir(testResources.getLeft()) > 1);
        });
        Thread.sleep(5000);
        // shutdown all node
        node1.shutdown();
        node2.shutdown();
        log.info("==========================================All node is done========================================");
        Thread.sleep(10000);
        node1 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        node2 = SeaTunnelServerStarter.createHazelcastInstance(seaTunnelConfig);
        log.info("==========================================All node is start, begin check node size ========================================");
        // waiting all node added to cluster
        HazelcastInstanceImpl restoreFinalNode = node1;
        Awaitility.await().atMost(60000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals(2, restoreFinalNode.getCluster().getMembers().size()));
        log.info("==========================================All node is running========================================");
        engineClient = new SeaTunnelClient(clientConfig);
        ClientJobProxy newClientJobProxy = engineClient.createJobClient().getJobProxy(jobId);
        CompletableFuture<JobStatus> waitForJobCompleteFuture = CompletableFuture.supplyAsync(newClientJobProxy::waitForJobComplete);
        Thread.sleep(10000);
        Awaitility.await().atMost(100000, TimeUnit.MILLISECONDS).untilAsserted(() -> {
            // Wait job write all rows in file
            Thread.sleep(2000);
            System.out.println("\n=================================" + FileUtils.getFileLineNumberFromDir(testResources.getLeft()) + "=================================\n");
            JobStatus jobStatus = null;
            try {
                jobStatus = newClientJobProxy.getJobStatus();
            } catch (Exception e) {
                log.error(ExceptionUtils.getMessage(e));
            }
            Assertions.assertTrue(JobStatus.RUNNING.equals(jobStatus) && testRowNumber * testParallelism == FileUtils.getFileLineNumberFromDir(testResources.getLeft()));
        });
        // sleep 10s and expect the job don't write more rows.
        Thread.sleep(10000);
        log.info("==========================================Cancel Job========================================");
        newClientJobProxy.cancelJob();
        Awaitility.await().atMost(600000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertTrue(waitForJobCompleteFuture.isDone() && JobStatus.CANCELED.equals(waitForJobCompleteFuture.get())));
        // prove that the task was restarted
        Long fileLineNumberFromDir = FileUtils.getFileLineNumberFromDir(testResources.getLeft());
        Assertions.assertEquals(testRowNumber * testParallelism, fileLineNumberFromDir);
    } finally {
        log.info("==========================================Clean test resource ========================================");
        if (engineClient != null) {
            engineClient.shutdown();
        }
        if (node1 != null) {
            node1.shutdown();
        }
        if (node2 != null) {
            node2.shutdown();
        }
    }
}

