@Test
public void testSavePointAndRestoreWithSavePoint() throws Exception {
    Common.setDeployMode(DeployMode.CLIENT);
    String filePath = TestUtils.getResource("/streaming_fake_to_console.conf");
    JobConfig jobConfig = new JobConfig();
    jobConfig.setName("streaming_fake_to_console.conf");
    SeaTunnelClient seaTunnelClient = createSeaTunnelClient();
    JobClient jobClient = seaTunnelClient.getJobClient();
    try {
        ClientJobExecutionEnvironment jobExecutionEnv = seaTunnelClient.createExecutionContext(filePath, jobConfig);
        final ClientJobProxy clientJobProxy = jobExecutionEnv.execute();
        CompletableFuture.supplyAsync(clientJobProxy::waitForJobComplete);
        long jobId = clientJobProxy.getJobId();
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("RUNNING", jobClient.getJobStatus(jobId)));
        RetryUtils.retryWithException(() -> {
            jobClient.savePointJob(jobId);
            return null;
        }, new RetryUtils.RetryMaterial(Constant.OPERATION_RETRY_TIME, true, exception -> {
            // If we do savepoint for a Job which initialization has not been
            // completed yet, we will get an error.
            // In this test case, we need retry savepoint.
            return exception.getCause().getMessage().contains("Task not all ready, savepoint error");
        }, Constant.OPERATION_RETRY_SLEEP));
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("FINISHED", jobClient.getJobStatus(jobId)));
        Thread.sleep(1000);
        seaTunnelClient.restoreExecutionContext(filePath, jobConfig, jobId).execute();
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("RUNNING", jobClient.getJobStatus(jobId)));
        jobClient.cancelJob(jobId);
        await().atMost(30000, TimeUnit.MILLISECONDS).untilAsserted(() -> Assertions.assertEquals("CANCELED", jobClient.getJobStatus(jobId)));
    } catch (Exception e) {
        throw new RuntimeException(e);
    } finally {
        seaTunnelClient.close();
    }
}

