@Test
public void testCatalogNameAndSourceTableNameBothSupport() {
    SQLEngine sqlEngine = SQLEngineFactory.getSQLEngine(SQLEngineFactory.EngineType.ZETA);
    SeaTunnelRowType rowType = new SeaTunnelRowType(new String[] { "id", "name", "age" }, new SeaTunnelDataType[] { BasicType.INT_TYPE, BasicType.STRING_TYPE, BasicType.INT_TYPE });
    sqlEngine.init("test", null, rowType, "select * from test");
    sqlEngine.init("test", "nameFromCatalog", rowType, "select * from test");
    sqlEngine.init("test", "nameFromCatalog", rowType, "select * from nameFromCatalog");
    Assertions.assertThrows(TransformException.class, () -> sqlEngine.init("test", "nameFromCatalog", rowType, "select * from unknown"));
    Assertions.assertThrows(TransformException.class, () -> sqlEngine.init("test", null, rowType, "select * from unknown"));
}

